:root {
  --bg: #0a1120;
  --bg-2: #0e1830;
  --panel: #12203c;
  --panel-2: #16284a;
  --line: #24365c;
  --text: #e8eefc;
  --sub: #8fa2c7;
  --amber: #f5b942;
  --amber-dim: #c28f2a;
  --pos: #4fd18b;
  --neg: #f2707a;
  --chain-eth: #8ea6ff;
  --chain-l2: #5fd4d0;
  --chain-sol: #c79bff;
  --chain-alt: #f2a25c;
  --radius-control: 7px;
  --radius-panel: 12px;
  --font-body: system-ui, -apple-system, "Segoe UI", sans-serif;
