* { box-sizing: border-box; }
html { color-scheme: dark; }
html, body { margin: 0; padding: 0; }
body { background: linear-gradient(180deg, var(--bg) 0%, var(--bg-2) 100%); color: var(--text); font: 400 15px/1.5 var(--font-body); min-height: 100vh; }
