.skip { position: absolute; left: -9999px; top: 0; background: var(--amber); color: #10131a; padding: 8px 14px; z-index: 20; }
.skip:focus { left: 8px; }
:focus-visible { outline: 2px solid var(--amber); outline-offset: 2px; border-radius: 3px; }
.shell { max-width: 1240px; margin: 0 auto; padding: 0 20px 48px; }

.top { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 18px 0; border-bottom: 1px solid var(--line); flex-wrap: wrap; }
.brand { display: flex; align-items: center; gap: 10px; }
.mark { width: 14px; height: 14px; border-radius: 4px; background: conic-gradient(var(--amber) 0 40%, var(--amber-dim) 40% 75%, var(--neg) 75% 100%); display: inline-block; }
