.badge.sol { color: var(--chain-sol); border-color: var(--chain-sol); }
.badge.alt { color: var(--chain-alt); border-color: var(--chain-alt); }
.status { display: inline-block; font-size: 11px; color: var(--amber); border: 1px solid var(--amber-dim); border-radius: 999px; padding: 1px 9px; white-space: nowrap; }
.status.live { color: var(--sub); border-color: var(--line); }
.implied { min-width: 150px; }
.bar { height: 6px; background: rgba(36, 54, 92, 0.8); border-radius: 4px; overflow: hidden; margin-bottom: 4px; width: 130px; }
.bar i { display: block; height: 100%; background: linear-gradient(90deg, var(--amber-dim), var(--amber)); border-radius: 4px; }
.empty { padding: 40px 24px; text-align: center; }
.empty h2 { margin-bottom: 6px; }
.empty p { color: var(--sub); margin-bottom: 14px; }
.button { background: var(--panel-2); color: var(--text); border: 1px solid var(--line); border-radius: var(--radius-control); padding: 8px 16px; }
.button.primary { background: var(--amber); color: #10131a; border-color: var(--amber); font-weight: 600; }

.model { padding: 18px 20px; margin-top: 22px; }
.model h2 { margin-bottom: 6px; font-size: 17px; }
