.model-list { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 8px 20px; margin: 10px 0 0; padding: 0; list-style: none; }
.model-list li { color: var(--sub); font-size: 13px; }
.model-list b { color: var(--text); }

.detail { background: var(--panel); color: var(--text); border: 1px solid var(--line); border-radius: 14px; padding: 0; max-width: 680px; width: calc(100vw - 32px); box-shadow: 0 18px 60px rgba(0, 0, 0, 0.6); }
.detail::backdrop { background: rgba(4, 8, 18, 0.72); }
.detail-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; padding: 20px 22px 12px; border-bottom: 1px solid var(--line); }
.detail-head h2 { margin: 4px 0; font-size: 22px; }
.detail-head .sub { margin-top: 4px; }
.close { background: none; border: 1px solid var(--line); color: var(--sub); border-radius: var(--radius-control); padding: 6px 12px; }
.close:hover { color: var(--amber); border-color: var(--amber-dim); }
.detail-section { padding: 16px 22px; border-bottom: 1px solid var(--line); }
.detail-section:last-child { border-bottom: 0; }
.detail-section h3 { margin-bottom: 10px; font-size: 13px; text-transform: uppercase; letter-spacing: 0.08em; color: var(--amber); }
.equation { display: grid; grid-template-columns: 1fr auto; gap: 6px 18px; margin-bottom: 10px; font-family: var(--font-num); font-size: 13px; }
.equation span { color: var(--sub); }
.equation b { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.equation .total { color: var(--amber); font-size: 17px; border-top: 1px solid var(--line); padding-top: 6px; }
.why { background: rgba(245, 185, 66, 0.08); border-left: 3px solid var(--amber); border-radius: 0 8px 8px 0; padding: 10px 14px; font-size: 13.5px; }
.steps { margin: 0; padding-left: 22px; }
