.sub-note { color: var(--sub); font-size: 12.5px; margin-top: 8px; }

@media (max-width: 760px) {
  .lede { flex-direction: column; }
  .facts { grid-template-columns: 1fr 1fr; width: 100%; }
  .count { margin-left: 0; width: 100%; }
  input[type="search"], select { min-width: 0; width: 100%; }
  .field { flex: 1 1 100%; }
}
